const e="prj_lochinvar",t="prj_borrowdale",a="prp_atlanta",o="prp_manchester",n="prp_capetown",s="prp_hillside",r="prj_avondale",i="prj_mabelreign",l=[{slug:"put-a-place-on-the-record",title:"Put a place on the record before you buy anything",forWhom:["owner","manager","tenant"],minutes:3,situation:"An account with nothing on it, and a house you want a history for. No check ordered, nothing paid.",claims:[{says:"An account with nothing on it",person:"usr_newcomer",holdsNothing:!0}],steps:[{say:"The record is the product and it is free. A place goes on it with a name, a city and whatever else you happen to know, and everything after that hangs off it: the repairs, the people, the condition, the paper. Nothing here asks you to buy a check first.",tryIt:{as:"usr_newcomer",to:"/properties/new",label:"Add one as Nomsa, who has nothing yet"}},{say:"Fill in what you actually know and leave the rest. A field you guess at is worse than an empty one, because in two years nobody will remember which was which. Everything stays editable."},{say:"Where it is not yours, say whether you look after it for its owner or are building it for them, and you keep it in that part until they take it. Where it is being built, the next screen asks for the rooms off the plan, so everything photographed during the build has a room to go in."},{say:"The place now exists and has a page. From here you can write down what is in it, note something that happened, keep a document, or ask somebody to go and look. All of that is the record, and only the last one costs anything.",showing:{propertyId:e}},{say:"This is what one looks like after a while. A repair, who reported it, what somebody independent saw, and what the owner decided, all on the same page as the house rather than in four different inboxes.",showing:{propertyId:e,requestId:"req_geyser",eventId:"ev_gy_1"},tryIt:{as:"usr_farai",to:`/properties/${e}/history`,label:"Read a full one as Farai"}}],seeAlso:[{to:"/how-it-works",label:"What the record is made of"}]},{slug:"a-repair-you-are-asked-to-pay-for",title:"The manager says the geyser is fixed. Do you pay?",forWhom:["owner","manager"],minutes:5,situation:"One repair at the Lochinvar house, over four days: a claim from the manager, a plumber behind it, an independent look, and a decision.",steps:[{say:"Sekai manages the house. A claim arrives: the geyser element failed, her plumber replaced it along with the thermostat, hot water is back on, invoice attached. She is a party to the situation, so however carefully she wrote it, the record stamps it Self-reported and shows the figure as reported rather than as fact.",claims:[{says:"the record stamps it Self-reported",level:"self-reported"},{says:"shows the figure as reported rather than as fact",amount:"reported"},{says:"Sekai manages the house. A claim arrives",by:"usr_sekai"}],showing:{propertyId:"prj_lochinvar",requestId:"req_geyser",eventId:"ev_gy_1"},tryIt:{as:"usr_sekai",to:"/properties/prj_lochinvar/requests/req_geyser",label:"Read it as Sekai, who filed it"}},{say:"None of that means she is wrong. It means you are holding one side of it. Read under each finding and the record already says where it came from: the photograph reached her from the plumber, and the finish date is what he told her on the phone.",claims:[{says:"the finish date is what he told her on the phone",findingLevel:"reported"}],showing:{propertyId:"prj_lochinvar",requestId:"req_geyser",eventId:"ev_gy_1",findingLabel:"Finished on"}},{say:"Farai does not want a plumbing report. He wants to know the unit exists and matches the invoice before money moves. That is the shallow end of the ladder, and for a repair this size it is the right rung to reach for.",tryIt:{as:"usr_farai",to:"/properties/prj_lochinvar/requests/req_geyser",label:"Order one as Farai"}},{say:"Blessing went out. Unit on the wall and plumbed in, nameplate legible and matching the invoice, hot water at the tap after two minutes. He has no stake in whether the invoice gets paid, so what he saw himself carries his own stamp rather than the plumber’s.",claims:[{says:"He has no stake in whether the invoice gets paid",competence:"peer"},{says:"what he saw himself carries his own stamp",level:"observed"}],showing:{propertyId:"prj_lochinvar",requestId:"req_geyser",eventId:"ev_gy_2"}},{say:"One line in his report does not carry it. The old unit was gone before he arrived, and the only account of where it went is the plumber’s, so that line stays attributed to the plumber inside an independent report. Provenance sits on the finding, not on the report.",claims:[{says:"that line stays attributed to the plumber",findingLevel:"reported"}],showing:{propertyId:"prj_lochinvar",requestId:"req_geyser",eventId:"ev_gy_2",findingLabel:"Old unit"}},{say:"The report also says what nobody looked at, and that is the sentence that decides whether this is finished. If what you are carrying is the risk of a bad installation, this was the wrong rung and you want somebody qualified. If it is the risk of paying for a unit that never arrived, you now know.",claims:[{says:"The report also says what nobody looked at",event:"ev_gy_2",notAssessed:!0}]},{say:"Farai approves up to the invoiced figure and writes down why. The decision lands on the record beside the claim and the look, so in two years the reason is still attached to the payment and nobody has to remember it.",claims:[{says:"approves up to the invoiced figure",decision:"approve",approvesAmountOf:"ev_gy_1"}],showing:{propertyId:"prj_lochinvar",requestId:"req_geyser",eventId:"ev_gy_3"},tryIt:{as:"usr_farai",to:"/properties/prj_lochinvar/requests/req_geyser",label:"Read the whole thing as Farai"}}],scopeNote:"This gets you to a decision you can defend. It does not cover disputing an invoice, setting approval rules so a repair this size never reaches you, or what to do when the look contradicts the claim.",seeAlso:[{to:"/evidence",label:"What the stamp on each entry means"},{to:"/checks",label:"What each depth of check actually covers"}]},{slug:"what-observed-tells-you",title:"Somebody looked. What does that actually tell you?",forWhom:["owner","manager"],minutes:4,situation:"One geyser at the Lochinvar house, and everything anybody has ever said about it.",steps:[{say:"A thing on the record has a life of its own. Here is the geyser: when it was commissioned, what failed, who replaced it and what somebody independent saw afterwards. Every line carries the stamp it earned rather than the one the reader would like it to have.",showing:{propertyId:e,assetId:"ast_loch_geyser"},tryIt:{as:"usr_farai",to:`/properties/${e}/things/ast_loch_geyser`,label:"Open the geyser as Farai"}},{say:"The plumber who did the work is the best-informed person about it and the worst-placed to be believed about it. He wants paying. That is not an accusation, it is why the stamp exists, and the record gives the same one to a careless message and a meticulous one.",claims:[{says:"The plumber who did the work",by:"usr_elias"},{says:"You want paying, which is why it is stamped this way",level:"self-reported"}],showing:{propertyId:e,requestId:"req_geyser_contractor",eventId:"ev_gc_1"}},{say:"Somebody with nothing riding on the outcome went and looked. That moves the lines he saw for himself, and only those.",claims:[{says:"Somebody with nothing riding on the outcome went and looked",competence:"peer"}],showing:{propertyId:e,requestId:"req_geyser",eventId:"ev_gy_2"}},{say:"Which is the part people get wrong. It is a fact about each line, not a grade on the report. Three of these he established himself and the fourth he is passing on, and the record refuses to launder the fourth by keeping it in good company.",claims:[{says:"Three of these he established himself and the fourth he is passing on",event:"ev_gy_2",findings:{observed:3,reported:1}}],showing:{propertyId:e,requestId:"req_geyser",eventId:"ev_gy_2",findingLabel:"Old unit"}},{say:"So when you read a line, read what is under it. The question is never whether the report is trustworthy. It is what this particular sentence is standing on, and the record answers that for every one."}],scopeNote:"This is about reading a record, not about buying one. Which depth of check to order, and what each one can and cannot establish, is a different question and has its own guide.",seeAlso:[{to:"/evidence",label:"The three levels, defined properly"},{to:"/how-it-works",label:"Why the record belongs to the place"}]},{slug:"which-check-do-i-need",title:"Which check do I actually need?",forWhom:["owner","manager"],minutes:3,situation:"Three situations a week throws up, and the rung each one is asking for.",steps:[{say:"Start from what you are afraid of rather than from the menu. The depths differ in one thing: how close somebody gets and what they are qualified to say once they are there."},{say:"You only need to know whether anything is happening. Has the delivery arrived, is the site still empty, is the roof on. Somebody stands at the boundary and photographs it, and nobody goes inside.",tier:"quick-look",tryIt:{as:"usr_farai",to:"/looks/new",label:"Order one as Farai"}},{say:"You need somebody inside, looking at the specific thing, comparing what is there against what was claimed. Right for a repair you are being invoiced for, where the question is whether the work exists and matches the paper.",tier:"peer"},{say:"You need somebody qualified to say whether it was done correctly, and to put their name on that. Right before a large payment, and the only honest answer for anything electrical, structural or plumbed, whatever the figure is.",tier:"professional",tryIt:{as:"usr_farai",to:"/inspections/new",label:"Order one as Farai"}},{say:"Buying shallow is not a mistake as long as you read the result for what it is. Every report says what it did not look at, and that sentence is what tells you whether to stop or to go deeper.",claims:[{says:"Every report says what it did not look at",notAssessed:!0}],showing:{propertyId:e,requestId:"req_geyser",eventId:"ev_gy_2"}}],scopeNote:"This helps you choose. It does not price the ladder, and it does not decide for you where the rules already require a qualified check regardless of what you would have picked.",seeAlso:[{to:"/checks",label:"What each depth can and cannot establish"},{to:"/evidence",label:"What the result will be stamped"}]},{slug:"money-for-a-builder",title:"The builder wants more money. Is the site ready for it?",forWhom:["owner"],minutes:8,situation:"A funding request on the Borrowdale build, held, revised, and approved three weeks later at a different figure, and the slab before it, paid as a stage.",steps:[{say:"Alfred is building the house and needs money for roof timber before prices move again. There is a supplier pro-forma attached. Everything about the ask is his, including the urgency.",claims:[{says:"There is a supplier pro-forma attached",photographed:!0},{says:"Everything about the ask is his",by:"usr_sibanda",amount:"reported"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_1"},tryIt:{as:"usr_sibanda",to:`/properties/${t}/requests/req_roof_timber`,label:"Read the ask as Alfred, who made it"}},{say:"Two questions, and they are independent. Is the figure reasonable, and is the building ready for the thing it buys. Answering only the first is how money arrives on site months early and leaves again."},{say:"A peer priced comparable timber from a yard on the same road. He is careful to say it is not a quote and he did not price this list, so the figure sits on the record as what a comparable load went for, which is exactly as much as it is worth.",claims:[{says:"A peer priced comparable timber",competence:"peer"},{says:"he is careful to say it is not a quote",amount:"observed"},{says:"what a comparable load went for",belowAmountOf:"ev_rt_1"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_2"}},{say:"And somebody went and stood there. The walls are not up to the height that receives a roof. Nothing on site is ready for what the money buys, which no amount of price checking would have found.",claims:[{says:"somebody went and stood there",competence:"quick-looker"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_3"}},{say:"So Farai holds it, and says what would change his mind: walls at plate height, and a priced list per item. A hold with conditions is a different thing from a refusal, and the contractor now knows what to come back with.",claims:[{says:"So Farai holds it",by:"usr_farai",decision:"hold"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_4"}},{say:"Two weeks later the walls are up and the list is itemised, at a figure well below the original. Still the contractor saying so.",claims:[{says:"at a figure well below the original",belowAmountOf:"ev_rt_1"},{says:"Still the contractor saying so",by:"usr_sibanda"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_5"}},{say:"This time a qualified check, because the money is large and the question is structural. Level within tolerance, ready for timber, quantities consistent with the span. That is a judgement somebody is putting their name to, not a photograph.",claims:[{says:"a judgement somebody is putting their name to",level:"verified"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_6"}},{say:"Approved against the itemised list rather than the original ask, with the reason attached. The whole sequence stays on the property, so the next person to fund a stage here can read what happened at this one.",claims:[{says:"Approved against the itemised list rather than the original ask",decision:"approve",approvesAmountOf:"ev_rt_5"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_7"},tryIt:{as:"usr_farai",to:`/properties/${t}/requests/req_roof_timber`,label:"Read the whole sequence as Farai"}},{say:"Before money goes, you can ask him to show you. A link from the request asks for the photographs you name, and a shot you mark as it is now takes only one taken through the page at that moment.",tryIt:{as:"usr_farai",to:`/properties/${t}/requests/req_roof_timber`,label:"Ask him as Farai"}},{say:"A stage is paid as a stage. The slab was asked for with the steel tied, approved, and said to be poured, all in the words of the two of them, and then paid.",claims:[{says:"asked for with the steel tied",event:"ev_sl_1",by:"usr_sibanda",photographed:!0},{says:"approved",event:"ev_sl_2",decision:"approve",approvesAmountOf:"ev_sl_1"},{says:"said to be poured",by:"usr_sibanda",photographed:!0}],showing:{propertyId:t,requestId:"req_bdale_slab",eventId:"ev_sl_3"}},{say:"The payment keeps what the record held the day it was recorded: every line on the request filed before it, each with whose word it was, and nothing filed after.",tryIt:{as:"usr_farai",to:`/properties/${t}/money?pay=pay_borrowdale_slab`,label:"Open the payment as Farai"}}],scopeNote:"This is one funding decision and one stage paid. It does not cover agreeing a schedule of payments with a contractor, or what to do when a site goes quiet for a month.",seeAlso:[{to:"/checks",label:"When a qualified check is the only honest one"},{to:"/evidence",label:"Why a price from a peer is not a quote"}]},{slug:"before-it-is-covered",title:"The plaster goes on next week. What should be photographed before it does?",forWhom:["owner","contractor","caretaker"],minutes:3,situation:"The Borrowdale build at the first fix, with the wiring and the pipes still in the open walls.",steps:[{say:"Open the build. Under the stage it has reached, the page lists what the next stage will hide, room by room: the wiring and the pipes before the plaster, the footings and the drains before the slab.",showing:{propertyId:t},tryIt:{as:"usr_farai",to:`/properties/${t}`,label:"See the list as Farai"}},{say:"Whoever is on site takes them, usually the builder, and each photograph goes on in their name. The page for each line says what is worth a photograph, so nobody has to know what a plumber will want in ten years.",tryIt:{as:"usr_sibanda",to:`/properties/${t}`,label:"Take them as Alfred"}},{say:"When it is covered, somebody says so, and the line goes away. The photographs stay in the room they were taken in, dated, so the kitchen keeps what went into its walls.",tryIt:{as:"usr_farai",to:`/properties/${t}/rooms/spc_bdale_kitchen`,label:"Open the kitchen as Farai"}},{say:"After the handover the room still has them, and the pack for a buyer carries them, room by room. Years later they say where to drill and where not to."}],scopeNote:"A photograph shows what was there on the day, in the word of whoever took it. It does not say the work was done well, and nothing here takes the place of a check.",seeAlso:[{to:"/evidence",label:"What a photograph in somebody’s word is worth"},{to:"/how-it-works",label:"Why every entry says who wrote it"}]},{slug:"deliveries-and-changes",title:"Cement arrived and the kitchen door moved. Where does that go?",forWhom:["owner","contractor","caretaker"],minutes:3,situation:"The Borrowdale build, with a load of cement at the gate and a door moved off the drawing.",steps:[{say:"Something arrived: say what came, how much as the supplier’s note says it, from whom and where it was put, with a photograph of the load. The note itself can go with the place as paper.",tryIt:{as:"usr_sibanda",to:`/properties/${t}/delivered`,label:"Write one down as Alfred"}},{say:"Nothing adds the deliveries up. There is no total and no count of what is left, because a figure worked out from them would read as stock that nobody counted."},{say:"Something that stays in the house, a geyser or a window, asks once it is written down whether it has gone in, and adds it to the house with its paper."},{say:"Something changed from the plan: what was expected, what it is now, why, and who proposed it, on the rooms it changed, with a photograph or the message that agreed it. A payment on the record can be named as what it cost.",tryIt:{as:"usr_farai",to:`/properties/${t}/changed`,label:"Write one down as Farai"}},{say:"Both are in the History in the name of whoever wrote them. A change says who asked for it, never whether it was allowed.",tryIt:{as:"usr_farai",to:`/properties/${t}/history`,label:"Read them as Farai"}}],seeAlso:[{to:"/how-it-works",label:"Why a delivery is a line and never a stock count"}]},{slug:"money-sent-ahead",title:"You send a relative money to pay the builder. How do you see where it went?",forWhom:["owner","caretaker"],minutes:3,situation:"The Avondale renovation, which Farai’s aunt Grace minds with money he sends ahead.",steps:[{say:"Record what you sent as money sent ahead to spend, paid to the relative on the record. They read it because it was paid to them, and can say it arrived.",tryIt:{as:"usr_farai",to:`/properties/${r}/money`,label:"Open it as Farai"}},{say:"They record each payment out of it in their own word: the builder’s stage, the tiles from the hardware store, each with its receipt.",tryIt:{as:"usr_grace",to:`/properties/${r}/money`,label:"Record one as Grace"}},{say:"You read the two side by side, each with its own total, and no figure between them. A payment nobody recorded or cash out of somebody’s own pocket makes a balance wrong, and a wrong balance reads as somebody owing it."},{say:"What they never read is the builder’s quote or what you approved. If you want them to negotiate and decide, make them the manager: one change, and everything filed is kept."},{say:"A builder who is not on the record can say a stage paid to them is what they have, through a link from whoever recorded paying it."}],seeAlso:[{to:"/how-it-works",label:"Where money sits on a place"}]},{slug:"the-builder-hands-it-over",title:"The builder says the house is finished. What do you write down at the handover?",forWhom:["owner"],minutes:3,situation:"The Borrowdale build, with its rooms named off the plan and its walls already photographed.",steps:[{say:"The walks of the build are under Condition. Your own visits are there, and so is the walk for the day the builder hands it over.",claims:[{says:"Your own visits are there",by:"usr_farai",level:"self-reported"}],showing:{propertyId:t,conditionId:"cond_bdale_walk_1"},tryIt:{as:"usr_farai",to:`/properties/${t}/condition`,label:"Open the walks as Farai"}},{say:"The handover walks the house, not the build: the rooms named off the plan and what went into them. The footings and the wiring stay in each room, where they were photographed before they were covered."},{say:"It asks how long your agreement gives the builder to come back, in months, or that it is not in writing. That is kept as your word about your own agreement."},{say:"From then on every report says how many months after the handover it was made, and a month before the time runs out you are told. It never says what the builder owes: that stays between the two of you."},{say:"The bathroom still has its pipes, as they were before the plaster went on.",tryIt:{as:"usr_farai",to:`/properties/${t}/rooms/spc_bdale_bath`,label:"Open the bathroom as Farai"}}],scopeNote:"A handover walk is your word about the house on the day. It is not an inspection, it releases no money, and nothing on the record says what anybody is obliged to put right.",seeAlso:[{to:"/evidence",label:"What a walk in your own word is worth"},{to:"/checks",label:"When an independent check at handover is worth it"}]},{slug:"condition-before-they-move-in",title:"Somebody is moving in. What do you write down first?",forWhom:["owner","manager","tenant"],minutes:4,situation:"The current tenancy at the Lochinvar house, recorded twice: once by the manager and once by the tenant.",steps:[{say:"A condition record is a walk through the place, line by line, with a photograph per line. It takes twenty minutes once and it is the thing every later argument measures against.",tryIt:{as:"usr_sekai",to:`/properties/${e}/condition/new`,label:"Start one as Sekai"}},{say:"Here is the manager walking the house on the day. Specific per line rather than a paragraph saying the house was clean, because a paragraph settles nothing eighteen months later.",claims:[{says:"the manager walking the house on the day",by:"usr_sekai",level:"self-reported"}],showing:{propertyId:e,conditionId:"cond_movein_manager"}},{say:"Then the tenant recorded his own, the next day, and the product keeps both. It does not merge them and it does not decide between them. Two accounts that agree are worth far more than one account nobody can question.",claims:[{says:"the tenant recorded his own",by:"usr_panashe",level:"self-reported"}],showing:{propertyId:e,conditionId:"cond_movein_tenant"},tryIt:{as:"usr_panashe",to:`/properties/${e}/condition`,label:"Read it as Panashe, who lives there"}},{say:"Both carry the stamp they earned. Each is a party to the tenancy, so neither is independent, and saying so plainly now is what stops either being waved as proof later. If a line genuinely matters, that is what an independent check is for."},{say:"Meter readings and keys are their own fields for the same reason. They are the two things that go missing from every handover and the two nobody can reconstruct afterwards.",claims:[{says:"Meter readings and keys are their own fields",hasMetersAndKeys:!0}],showing:{propertyId:e,conditionId:"cond_handover_lochinvar"}}],scopeNote:"This covers making the record. It does not cover deposits, what a tenancy agreement should say, or comparing a move-in against a move-out, which is the next guide.",seeAlso:[{to:"/evidence",label:"Why a careful record is still one side"},{to:"/how-it-works",label:"How a tenancy sits on the property"}]},{slug:"they-have-moved-out",title:"They have moved out and you disagree about the state of it",forWhom:["owner","manager"],minutes:4,situation:"A tenancy at the Lochinvar house that ran nearly a year, with a record at both ends.",steps:[{say:"This is what the tenant wrote down when she arrived. Her own account, her own photographs, filed the day after she got the keys.",claims:[{says:"Her own account, her own photographs",by:"usr_rudo_tenant",level:"self-reported"}],showing:{propertyId:e,conditionId:"cond_movein_rudo"}},{say:"And this is the walk at the end, done by somebody we sent rather than by either side. That is the asymmetry worth paying for: at move-out there is money on the table, so the account of the place stops being something either party should be writing alone.",claims:[{says:"done by somebody we sent rather than by either side",level:"verified",competence:"inspector"}],showing:{propertyId:e,conditionId:"cond_moveout_rudo"}},{say:"Put side by side, line against line. What changed, what did not, and what nobody wrote down at the start and therefore cannot now claim. The rooms line up because both walks asked about the same parts.",claims:[{says:"The rooms line up because both walks asked about the same parts",condition:"cond_moveout_rudo",sameRoomsAs:"cond_movein_rudo"}],tryIt:{as:"usr_farai",to:`/properties/${e}/compare?before=cond_movein_rudo&after=cond_moveout_rudo`,label:"Compare them as Farai"}},{say:"A line missing from the first record is the one that costs you. There is no way to establish afterwards what a wall looked like before somebody lived against it for a year, and an honest record says so rather than guessing in the landlord’s favour."},{say:"Where a line is genuinely disputed and genuinely worth money, that is when to buy a check on that one item instead of arguing about the whole house.",tryIt:{as:"usr_farai",to:`/properties/${e}/checks`,label:"Order one as Farai"}},{say:"She keeps her side of it after she has gone. The comparison is hers as much as yours, and so is the pack for her deposit: both records side by side, both sets of photographs, and the deposit shown and never worked out against. She can send it by link to a deposit scheme by name, and every time they open it is a line in the history.",tryIt:{as:"usr_rudo_tenant",to:`/properties/${e}/packs`,label:"See it as Rudo, who moved out"}}],scopeNote:"This gets you to a side-by-side comparison. It does not decide a deposit, give legal advice, or adjudicate between two accounts. The product shows both and refuses to pick, and a pack sent by link tells whoever reads it, before anything else, that nobody checked it for them.",seeAlso:[{to:"/evidence",label:"Why the move-out record is stamped differently"},{to:"/checks",label:"Buying a check on one disputed item"}]},{slug:"report-without-approving",title:"Stop approving light bulbs from four thousand miles away",forWhom:["owner"],minutes:3,situation:"Two repairs at the same house, a fortnight apart, one of which needed the owner and one of which did not.",steps:[{say:"The tenant reports a dead light fitting. The manager gets an electrician to look, who quotes for the part and the labour. Then the whole thing stops and waits for somebody in another country to press a button.",claims:[{says:"waits for somebody in another country",by:"usr_farai",livesAbroad:!0},{says:"press a button",decision:"approve"}],showing:{propertyId:e,requestId:"req_kitchen_light",eventId:"ev_kl_3"}},{say:"Nothing about that decision needed him. It needed somebody to say yes, and the person best placed to say yes was already standing in the kitchen. Meanwhile the tenant has no kitchen light for a week because of a time zone."},{say:"So you write the rule once. Below a figure you choose, whoever manages the property decides and you read about it afterwards. Above it, nothing moves without you. It is a band, not a switch, and you can require evidence before the bigger ones reach you at all.",tryIt:{as:"usr_farai",to:`/properties/${e}/policy`,label:"Set the bands as Farai"}},{say:"The geyser is what the top of the ladder is for. A larger figure, a system where bad work is dangerous rather than annoying, and a contractor you have never met. That one should reach you, and the rule is what makes sure the light fitting does not.",claims:[{says:"A larger figure",event:"ev_kl_2",belowAmountOf:"ev_gy_1"}],showing:{propertyId:e,requestId:"req_geyser",eventId:"ev_gy_1"}},{say:"Rules are written on you and inherited by every property you keep, so a building site can override them without you rewriting anything. A site where a contractor asks for money in thousands is not a house where somebody reports a dead bulb.",tryIt:{as:"usr_farai",to:`/properties/${t}/policy`,label:"See the override as Farai"}}],scopeNote:"A rule decides who may approve and what has to exist first. It cannot make somebody trustworthy, it does not review the work, and there are systems where it will refuse to let you delegate at all however small the figure is.",seeAlso:[{to:"/checks",label:"Where a qualified check is required regardless"},{to:"/how-it-works",label:"Who takes part in a property"}]},{slug:"a-fault-comes-in-and-you-price-it",title:"A fault comes in and the owner is asleep",forWhom:["manager","owner"],minutes:4,situation:"A dead light at the Lochinvar house, from the moment the tenant reports it to the moment somebody can decide about it.",steps:[{say:"Panashe lives there and the kitchen light has stopped. He has already swapped the bulb and checked the switch, and he says so. That is a complaint, and nobody can approve a complaint.",claims:[{says:"Panashe lives there and the kitchen light has stopped",by:"usr_panashe"}],showing:{propertyId:e,requestId:"req_kitchen_light",eventId:"ev_kl_1"}},{say:"Your job is to turn it into something decidable. Get somebody to look, find out what it costs, and put both on the record where the owner will see them. The gap between those two entries is most of what you are paid for.",claims:[{says:"put both on the record",by:"usr_sekai",amount:"reported"}],showing:{propertyId:e,requestId:"req_kitchen_light",eventId:"ev_kl_2"},tryIt:{as:"usr_sekai",to:`/properties/${e}/requests/req_kitchen_light`,label:"Work it as Sekai"}},{say:"Say where the figure came from. A verbal quote from an electrician is worth exactly that, and writing it down as a verbal quote is what lets an owner four thousand miles away weigh it properly instead of either trusting it blindly or doubting all of it."},{say:"A bigger one works the same way, and this is where it pays to be unbothered. You file what your plumber told you, the owner buys a look before paying, and somebody independent goes out. That is not about you. It is what the record costs when money moves.",claims:[{says:"You file what your plumber told you",by:"usr_sekai",level:"self-reported"}],showing:{propertyId:e,requestId:"req_geyser",eventId:"ev_gy_1"}},{say:"What you may settle yourself is the owner’s rule rather than your judgement, and the house’s requests tell you which of those you are holding. Anything waiting on somebody else sits there saying so, and anything waiting on you is counted on the house on your home screen and is the first thing you see when you open it.",tryIt:{as:"usr_sekai",to:`/properties/${e}/requests`,label:"Open the house’s requests as Sekai"}}],scopeNote:"This is the reporting half. It does not cover ordering a check, which is the owner’s to buy, or changing what you are allowed to approve, which is the owner’s to set.",seeAlso:[{to:"/evidence",label:"Why what you file is stamped the way it is"},{to:"/how-it-works",label:"How a request moves"}]},{slug:"something-has-stopped-working",title:"Something in the house has stopped working",forWhom:["tenant"],minutes:3,situation:"The kitchen light at the Lochinvar house, reported by the person who lives with it.",steps:[{say:"Say what it is and what you already tried. Two sentences beat a paragraph, and what you have ruled out is the useful part: it stops somebody being sent to do the thing you did on Tuesday.",claims:[{says:"what you have ruled out is the useful part",by:"usr_panashe"}],showing:{propertyId:e,requestId:"req_kitchen_light",eventId:"ev_kl_1"},tryIt:{as:"usr_panashe",to:`/properties/${e}/requests/new`,label:"Report one as Panashe"}},{say:"What you said is on the record as yours, with your name and the day you said it. Nobody edits it later and nobody can claim you never mentioned it. That is the whole reason to use this rather than a message that scrolls away."},{say:"Then you can watch it move. Priced, decided, done, each by a named person. You are not chasing anybody and you are not guessing whether it was passed on.",claims:[{says:"Priced, decided, done, each by a named person",by:"usr_elias"}],showing:{propertyId:e,requestId:"req_kitchen_light",eventId:"ev_kl_4"}},{say:"The record you make when you arrive is the one that matters most and the one people skip. Walk the rooms with a camera on the day. It is yours, it is measured against at the end, it stays yours after you move out, and it takes twenty minutes once.",claims:[{says:"It is yours",by:"usr_panashe",level:"self-reported"}],showing:{propertyId:e,conditionId:"cond_movein_tenant"},tryIt:{as:"usr_panashe",to:`/properties/${e}/condition`,label:"Read it as Panashe"}},{say:"What you will not see is the rest of the house’s business: the owner’s rules, other tenancies, what anything cost before you got here. You see your tenancy and what you put on it."}],scopeNote:"This covers reporting and recording. It gives no advice about deposits, notice or your agreement, and it holds no money. When you move out, the pack for your deposit is your own two records side by side, to hand to whoever you choose, and it says nothing about who owes what.",seeAlso:[{to:"/evidence",label:"Why your own record still says self-reported"},{to:"/how-it-works",label:"What the record keeps"}]},{slug:"you-did-the-work-and-want-paying",title:"You did the work and you want paying for it",forWhom:["contractor"],minutes:4,situation:"Two jobs from the tradesman’s side: a geyser already replaced, and roof timber not yet bought.",steps:[{say:"Show the job as you did it. What was wrong, what you replaced, what you tested, photographed while you were standing there. It costs you five minutes on site and it is the difference between being paid this week and answering questions next week.",claims:[{says:"photographed while you were standing there",photographed:!0},{says:"Show the job as you did it",by:"usr_elias"}],showing:{propertyId:e,requestId:"req_geyser_contractor",eventId:"ev_gc_1"},tryIt:{as:"usr_elias",to:`/properties/${e}/requests/req_geyser_contractor`,label:"File it as Elias"}},{say:"It gets stamped as coming from a party to the job, and that is not an insult. You want to be paid, which is exactly why your account of it cannot also be the independent one. Good photographs do not change the stamp and they do change how fast somebody says yes."},{say:"Asking for money before you start is the same discipline, itemised. A round number with a pro-forma behind it is a number somebody has to take on trust, and trust is slower than a list.",claims:[{says:"a round number with a pro-forma behind it",by:"usr_sibanda",amount:"reported"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_1"},tryIt:{as:"usr_sibanda",to:`/properties/${t}/requests/req_roof_timber`,label:"Ask as Alfred"}},{say:"This one was held, and the hold said what would change it: walls at plate height, and a price per item. That is a far better answer than silence, because it is a list you can go and satisfy.",claims:[{says:"This one was held",decision:"hold"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_4"}},{say:"So he came back with both, and it was approved against the itemised list. The record now shows a contractor who does what he says, which is worth more on the next job than the argument would have been.",claims:[{says:"it was approved against the itemised list",decision:"approve",approvesAmountOf:"ev_rt_5"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_7"}},{say:"An owner can ask you by link to show them. The page lists the photographs they want: take them through it where you stand. One you already had says so, and a shot they want as it is now takes only one taken there and then."},{say:"When somebody records paying you and you are not on their record, they can send it to you by link. It says what they recorded paying you and what for, and you say whether it is what you have."}],scopeNote:"This is how to be believed quickly. It does not get you paid: the money moves between you and whoever engaged you, and this product holds the record rather than the funds.",seeAlso:[{to:"/evidence",label:"Why a party to the job is stamped that way"},{to:"/checks",label:"What somebody independent will and will not do"}]},{slug:"build-it-for-a-client",title:"You are building a house for somebody. Can you keep its record and hand it to them?",forWhom:["contractor"],minutes:3,situation:"The Mabelreign house, which Alfred is building for a client who has not taken the record yet.",steps:[{say:"Add the place, and where it asks whose it is, say you are building it for somebody. You keep the record as the builder, never in the owner’s chair.",tryIt:{as:"usr_sibanda",to:"/properties/new",label:"Add one as Alfred"}},{say:"Name the rooms off the plan, then keep it as the job goes: where the build has got to, what the next stage will hide, what arrived and what changed. Each entry is in your name.",showing:{propertyId:i},tryIt:{as:"usr_sibanda",to:`/properties/${i}`,label:"Open it as Alfred"}},{say:"Authorising checks is your client’s to give, so it starts unasked. Nothing is ordered on your own work in their name."},{say:"When your client is ready, send them the code. The page it opens says who kept the record, as the builder, and since when, before they take anything."},{say:"Once they take it, the record is theirs. You stay on it as the builder, everything you filed keeps your name, and the History says on which day it changed hands."}],seeAlso:[{to:"/how-it-works",label:"Who keeps a record, and what changes when it changes hands"}]},{slug:"you-have-been-given-a-job",title:"You have been given a job. What are you actually answering?",forWhom:["inspector"],minutes:4,situation:"A workmanship review at the Hillside flat, assigned and not yet scheduled.",steps:[{say:"A job is a question, not an address. This one bought a judgement about whether work was done correctly, and it comes with the claim you are measuring against and the arrangement for getting in. Read all three before you go.",claims:[{says:"assigned and not yet scheduled",status:"inspector-assigned",unscheduled:!0},{says:"the claim you are measuring against and the arrangement for getting in",briefed:!0}],showing:{propertyId:"prj_hillside",inspectionId:"ins_015"},tryIt:{as:"usr_insp_blessing",to:"/jobs/ins_015",label:"Open it as Blessing"}},{say:"Answer the question you were asked. A customer who bought a view of whether the trusses are up is not helped by an opinion about the paintwork, and a customer who bought your judgement is not served by photographs alone."},{say:"Every finding carries its own basis. What you saw yourself, what you measured, and what somebody on site told you are three different things, and the record keeps them apart rather than averaging them into an impression.",claims:[{says:"What you saw yourself and what somebody told you are different things",findings:{observed:3,reported:1}}],showing:{propertyId:e,requestId:"req_geyser",eventId:"ev_gy_2"}},{say:"Then say what you did not assess. It is the part that feels like admitting a gap and it is the part that protects you: a reader who knows the pressure valve was not checked cannot later say your report implied it was.",claims:[{says:"say what you did not assess",event:"ev_gy_2",notAssessed:!0},{says:"a reader who knows it was not checked",findingLevel:"reported"}],showing:{propertyId:e,requestId:"req_geyser",eventId:"ev_gy_2",findingLabel:"Old unit"}},{say:"Your name goes on it, and it stays on the property for as long as the property exists. The next person to buy a check here reads what you wrote, which is the argument for writing it carefully.",claims:[{says:"Your name goes on it",level:"verified"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_6"},tryIt:{as:"usr_insp_blessing",to:"/my-reports",label:"Read the file as Blessing"}}],scopeNote:"This is about the work. It does not cover getting onto the panel, what a job pays, or the trades you declare, which decide which jobs reach you at all.",seeAlso:[{to:"/checks",label:"What each depth can and cannot establish"},{to:"/evidence",label:"Why the stamp sits on the finding"}]},{slug:"a-look-on-your-street",title:"Somebody wants a look at a place near you",forWhom:["looker"],minutes:3,situation:"An unclaimed look at the Borrowdale build, opened this morning and still on the board.",claims:[{says:"An unclaimed look, opened this morning and still on the board",look:"ql_open_01",status:"open"}],steps:[{say:"A look is a small paid errand at a place you were passing anyway. Somebody wants to know whether anything is happening, and they are not asking you what you think of it.",tryIt:{as:"usr_look_tafara",to:"/looker/mine",label:"See the board as Tafara"}},{say:"You never go inside and you never go through a gate. You stay on the public road, and that boundary is the whole basis of the arrangement."},{say:"Each frame is stamped with where your phone says you were standing when you took it, checked against the site. That is what makes a photograph from the road worth paying for rather than a picture that could be anywhere."},{say:"Then say what you saw and nothing else. This one is a good one to copy: it reports the walls as they were, states that nothing on site is ready for what was being bought, and says plainly that the brickwork was not assessed. That last line is what keeps it honest.",claims:[{says:"it reports the walls as they were",competence:"quick-looker",level:"observed"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_3"}},{say:"That look changed a decision worth thousands, from the pavement, in about ten minutes. You are not an inspector and you are not pretending to be one, and it mattered anyway.",claims:[{says:"That look changed a decision worth thousands",decision:"hold"}],showing:{propertyId:t,requestId:"req_roof_timber",eventId:"ev_rt_4"}}],scopeNote:"A look answers whether something is there. It never assesses quality, never enters a property, and is not an inspection however good the photographs are.",seeAlso:[{to:"/checks",label:"Where a look sits on the ladder"},{to:"/evidence",label:"What a look can and cannot be stamped"}]},{slug:"the-first-week-of-a-lease",title:"You have just signed a lease. What goes on the record in the first week?",forWhom:["tenant"],minutes:4,situation:"Nomsa’s apartment in Atlanta, on a lease she keeps her own record of.",steps:[{say:"Put the place on as somewhere you rent. It asks when you moved in, when the lease ends, the rent and the day it is due, and all of it is yours: the landlord is not on your record unless you bring them in.",tryIt:{as:"usr_nomsa",to:"/properties/new",label:"Add one as Nomsa"}},{say:"Then walk it before you unpack, room by room, with a photograph per line. It is what your security deposit is argued from when you leave, and the only time it can be made is now.",claims:[{says:"walk it before you unpack",by:"usr_nomsa",level:"self-reported"}],showing:{propertyId:a,conditionId:"cond_atl_movein"},tryIt:{as:"usr_nomsa",to:`/properties/${a}/condition`,label:"Read her move-in walk as Nomsa"}},{say:"Keep the lease with the place, and the deposit on the tenancy in the currency you paid it in. Nothing is worked out against it. It is there so the figure is not a matter of memory in a year.",tryIt:{as:"usr_nomsa",to:`/properties/${a}/documents`,label:"See her lease as Nomsa"}},{say:"Record the first month’s rent when it goes, with the receipt. From then on each month starts from what the lease says."}],scopeNote:"Your own walk is your word, dated and photographed. It is not an inspection, it does not say who caused anything later, and it does not tell you what a lease or a deposit law says where you live.",seeAlso:[{to:"/evidence",label:"What your own photographs can and cannot settle"},{to:"/how-it-works",label:"How a tenancy sits on a place"}]},{slug:"what-a-place-costs-you",title:"What does this place actually cost you, month by month?",forWhom:["tenant","owner"],minutes:3,situation:"Nomsa’s apartment in Atlanta, which she rents and keeps her own record of.",steps:[{say:"Rent goes on as a payment: the month it is for, what moved and when, with the receipt if there is one. The month starts from what the lease says, so most months it is a tap and a screenshot.",showing:{propertyId:a},tryIt:{as:"usr_nomsa",to:`/properties/${a}/money`,label:"Record a month as Nomsa"}},{say:"What comes every month is said once: the power, the internet, getting to work. Each is an estimate that repeats, and a month you actually paid is recorded against it, so the page can tell a guess from a receipt."},{say:"Then the page answers the question in the title, a month or a year at a time, in the currency each thing was paid in. Two currencies stay two totals. Nothing is converted and nothing is netted."},{say:"Who reads each line is the record’s decision, not yours to remember. Rent is between you and the owner, who can say it is what they received. What getting to work costs you is yours and reaches nobody."}],seeAlso:[{to:"/how-it-works",label:"Where money sits on a place"}]},{slug:"bring-somebody-onto-a-place",title:"Somebody else needs to be on this record. How do you bring them in?",forWhom:["owner","manager"],minutes:3,situation:"The Lochinvar house, which Farai owns, Sekai manages and Panashe rents.",steps:[{say:"Everybody on a place has one part in it: owner, manager, tenant, or the person who does the work. The people page lists them and what each part is.",showing:{propertyId:e},tryIt:{as:"usr_farai",to:`/properties/${e}/people`,label:"See who takes part as Farai"}},{say:"Bringing somebody in is an invitation for one part at this place and nothing else. It goes to their email as a link with a code, and redeeming it opens this place to them and nothing else you have."},{say:"Their part decides what they read, so there is nothing to remember to hide. A tenant reads their tenancy and the requests that are theirs to see, without the owner’s decisions and figures."},{say:"A part can end. A tenant who moves out keeps what was theirs to read and can write nothing more, and the record keeps that they were there."}],seeAlso:[{to:"/how-it-works",label:"Who takes part in a place"}]},{slug:"send-a-pack-outside-the-account",title:"A buyer, an insurer or a deposit scheme wants the record. What do you send?",forWhom:["owner","tenant"],minutes:3,situation:"The Lochinvar house, whose record has a few years of repairs, things and paper on it.",steps:[{say:"A pack is the part of the record one outside reader needs, put together for them: what is at the place for an inventory, what a new keeper needs for a handover, a move-in beside a move-out for a deposit, and what whoever is staying needs to know, as a house manual.",showing:{propertyId:e},tryIt:{as:"usr_farai",to:`/properties/${e}/packs`,label:"Open the packs as Farai"}},{say:"It goes as a link to one person you name. They need no account, the link stops working on the day it says, and you can withdraw it before then."},{say:"What they read is the record as it stands, every entry saying who said it and how far to trust it. A pack adds nothing to an entry it includes and leaves nothing out of it."},{say:"For a buyer, a house built on the record also carries what went into its walls, room by room, each photograph in the word of whoever took it.",tryIt:{as:"usr_farai",to:`/properties/${t}/packs?pack=handover`,label:"Open Borrowdale’s as Farai"}}],scopeNote:"A pack sends what the record already holds. It checks nothing new, and it says nothing about the place beyond what each entry says of itself.",seeAlso:[{to:"/evidence",label:"What the stamps in a pack mean"},{to:"/how-it-works",label:"What the record is made of"}]},{slug:"something-broke-tell-your-landlord",title:"Something broke. How do you tell your landlord or host and keep it on the record?",forWhom:["tenant"],minutes:3,situation:"Nomsa’s apartment in Atlanta, which she rents and keeps her own record of.",steps:[{say:"Press Record something and say something is broken. It asks where first, the room, then the thing in it and what is wrong with it, so you are choosing rather than hunting for the right words.",tryIt:{as:"usr_nomsa",to:`/properties/${a}/requests/new`,label:"Report one as Nomsa"}},{say:"Add a photograph of it from your phone and a line about what you have already tried. Both go on the report as yours, with your name and the time you sent it."},{say:"Send it, and the next screen says it is on the record before anything else. Then it offers one next step, and since a landlord or a host is never on a record you keep yourself, that step is sending it to them."},{say:"Sending makes a link to this one report, for one person you name. It goes from your own phone, by WhatsApp, a text, an email or a copy you paste, so it reaches them the way they already hear from you."},{say:"They open it without an account and see the report, its photographs and one question: have you seen it? Their answer comes back onto your report under the name you gave the link, marked as coming through it, and it is their word beside yours."},{say:"The report shows who you sent it to and whether they have opened it. A link takes one answer, and until it has one you can take it back."}],scopeNote:"A link asks one question about one report. It gets nothing fixed and moves no money, and whoever answers is whoever had the link: nobody checked who they are.",seeAlso:[{to:"/evidence",label:"Why an answer through a link is only ever their word"},{to:"/how-it-works",label:"Why every entry says who wrote it"}]},{slug:"get-the-rent-confirmed",title:"Your landlord is not on Den & Keyholder. Can they still confirm the rent?",forWhom:["tenant","owner"],minutes:3,situation:"Nomsa’s apartment in Atlanta, which she rents and keeps her own record of, rent included.",steps:[{say:"Record the month’s rent when it goes. The month starts from what your lease says, so it is usually one tap, with the receipt if you have one.",tryIt:{as:"usr_nomsa",to:`/properties/${a}/money`,label:"Open her rent as Nomsa"}},{say:"Open the payment. Where nobody from the other side is on your record, it offers to send it to whoever you paid, with the name the payment already gives them filled in."},{say:"The link goes from your own phone, like any message. They see one sentence, what you recorded paying them, on which day, how and for which month, and one question: is that what you have?"},{say:"They say yes, or that it is not what they have, with a line saying what they have instead. Either way it sits beside the payment in their name, through the link you sent, and what you recorded stays as you wrote it."},{say:"It is offered only on a payment you recorded yourself, only for money that passed between the two sides, and not once they have said anything about it. A landlord can send a deposit paid back to a tenant who has moved out the same way."}],scopeNote:"A confirmation is one person’s word, given through a link. It is not a bank’s record, it moves no money, and it says nothing about a month nobody recorded.",seeAlso:[{to:"/evidence",label:"Why their yes is their word and not a receipt"},{to:"/how-it-works",label:"Where money sits on a place"}]},{slug:"nothing-is-wrong-this-month",title:"Nothing is broken. Is there anything worth doing at home this month?",forWhom:["owner"],minutes:4,situation:"George’s house in Manchester, which he owns and lives in.",claims:[{says:"which he owns and lives in",person:"usr_george",livesAbroad:!1}],steps:[{say:"Open the place. When nothing is waiting on you, the home starts with what changed since you were last here, or says that nothing did.",showing:{propertyId:o},tryIt:{as:"usr_george",to:`/properties/${o}`,label:"Open it as George"}},{say:"This season is what people usually do at this time of year where you live, for the things your record actually has. It is there to read. Nothing ticks, nothing falls due, and nothing turns red if you leave it."},{say:"Then one question about your home, one at a time, such as where the water turns off. Answer it and it is kept in your word, with the day. Not today puts it away for a month."},{say:"Last comes one useful thing the record itself shows, such as a room nobody has photographed. Not today puts that away too."},{say:"Check my place is the short walk: three things, picked from what the season asks and what the record has, one to a screen. Say it looks as it did or that something has changed, and add a photograph if you like.",tryIt:{as:"usr_george",to:`/properties/${o}/check`,label:"Walk it as George"}},{say:"It is filed as one check in your word, beside the ones before it, so the next walk has something to be read against. Saying something has changed takes you on to report it, with the thing already chosen.",claims:[{says:"filed as one check in your word",by:"usr_george",level:"self-reported"}],showing:{propertyId:o,conditionId:"cond_man_autumn"}}],scopeNote:"Check my place is your own look, in your word. It is not an inspection, and what the season asks is what people usually do for that kind of thing, never a verdict on yours.",seeAlso:[{to:"/evidence",label:"Why your own walk is your word"},{to:"/how-it-works",label:"What the record keeps"}]},{slug:"keep-what-you-need-in-a-hurry",title:"Where does the water turn off? Keep what you will need in a hurry",forWhom:["owner","tenant"],minutes:4,situation:"George’s house in Manchester, which he owns and lives in.",claims:[{says:"which he owns and lives in",person:"usr_george",livesAbroad:!1}],steps:[{say:"The home asks one question at a time, and what you would need in a hurry comes first: where the water turns off, where the power goes off. A photograph answers most of them, and a few words do the rest.",showing:{propertyId:o},tryIt:{as:"usr_george",to:`/properties/${o}`,label:"See the question as George"}},{say:"An answer is kept as a note in your word, with the day, about that thing or that room. Answer again later and the newest is the one shown, while the old one stays in the history."},{say:"All of it is on one page. What you would need in a hurry comes first, then each thing and each room, every question with its answer or a way to answer it there, and what the year usually asks of the things you have, to read rather than to tick off.",tryIt:{as:"usr_george",to:`/properties/${o}/remember`,label:"Open it as George"}},{say:"It comes back where you would look for it: under Remember on the thing’s own page, beside what was done to it last.",tryIt:{as:"usr_george",to:`/properties/${o}/things/ast_man_stopcock`,label:"Open the stopcock as George"}},{say:"And on the page for its room, with what else is in there and what happened there. Anything you report from that page starts in that room.",tryIt:{as:"usr_george",to:`/properties/${o}/rooms/spc_man_kitchen`,label:"Open the kitchen as George"}},{say:"Find, at the top of any page of the place, searches what your part may read: the things, the rooms, the paper, the notes, the requests and the people. Type a word and go straight to where the answer sits."},{say:"Whoever is staying can have it too, as the house manual: a link for one person you name, read without an account. It carries what is kept, who to ring and what whoever lives there usually does, never money or paper, and it runs out on the day it says.",tryIt:{as:"usr_george",to:`/properties/${o}/packs?pack=manual`,label:"Send it as George"}},{say:"Codes and passwords never go here: not the alarm, not the wifi, not a lockbox. A record gets shared and handed on, and a secret written into it stops being one."}],seeAlso:[{to:"/how-it-works",label:"Why every entry says who wrote it"}]},{slug:"a-price-from-somebody-not-on-the-record",title:"The plumber is not on the record. How do you get a price onto it?",forWhom:["manager","owner"],minutes:3,situation:"The gate motor at the Lochinvar house, reported by the tenant and waiting on the manager for a price.",claims:[{says:"reported by the tenant",event:"ev_gm_1",by:"usr_panashe"}],steps:[{say:"A report waiting on a price is waiting on you. When the figure has to come from somebody who is not on the record, an electrician or a plumber you ring, send the report to them rather than retyping it.",claims:[{says:"A report waiting on a price",status:"reported"},{says:"the report, with its photographs",by:"usr_panashe",photographed:!0}],showing:{propertyId:e,requestId:"req_gate_motor",eventId:"ev_gm_1"},tryIt:{as:"usr_sekai",to:`/properties/${e}/requests/req_gate_motor`,label:"Open it as Sekai"}},{say:"The link carries this one report with its photographs and one question: what would it cost to fix? They open it without an account, and see the place by its name and town, never its street."},{say:"Their figure lands on the request as a price, in the name you sent it to, through the link, with whatever they add about when they could come."},{say:"From there it is decided the way any price here is. Send it to two people and you have two prices, each in its own name, to choose between."},{say:"If you own the place and nobody manages it for you, a report waits on you, and you can do the same."}],scopeNote:"A price through a link is the word of whoever opened it. It approves nothing and books nobody, and nobody checked who they are or whether they can do the work.",seeAlso:[{to:"/evidence",label:"Why a price through a link is only ever their word"},{to:"/how-it-works",label:"How a request moves"}]},{slug:"keep-a-record-of-a-stay",title:"Checking into a hotel or a hostel. How do you show what the room was like when you arrived?",forWhom:["guest"],minutes:3,situation:"Thandi’s three weeks in a Cape Town flat, which she keeps her own record of.",steps:[{say:"Press Start a stay and say where you are: a hotel, a hostel, a rental or somebody’s home. Give it the name on the booking and the room, and the next screen is the room itself.",tryIt:{as:"usr_thandi",to:"/stays/new",label:"Start one as Thandi"}},{say:"Walk it before you unpack, in your own words. The room offers what it usually has, the key card, the safe, the minibar, one tap each, and anything it does not know you write the way you would say it.",showing:{propertyId:n,conditionId:"cond_cpt_arrival"}},{say:"Photograph whatever is already marked or missing. Each photograph is dated and kept as yours, beside the line it is about."},{say:"On the last morning, walk it again. The walk asks about every line you wrote on the first evening, the minibar included, so the two walks line up.",tryIt:{as:"usr_thandi",to:`/properties/${n}/condition/new?kind=move-out`,label:"Walk out as Thandi"}},{say:"Then say you have left. The stay ends on your record, and the two walks are set side by side, line by line."},{say:"If a charge arrives after you have gone, send the two walks to whoever made it, by a link from your own phone. They read them without an account."}],scopeNote:"Both walks are your word, dated and photographed. Nobody checked them, they say nothing about a room you did not walk, and they settle no bill: they are what you can show.",seeAlso:[{to:"/evidence",label:"Why your own walk is your word, and still worth keeping"},{to:"/how-it-works",label:"One small place for each stay"}]},{slug:"look-after-a-place-for-somebody",title:"You look after a house for somebody who lives far away. What goes on the record?",forWhom:["caretaker"],minutes:3,situation:"Hillside house in Bulawayo, which Kudzai looks after for its owner, his cousin Farai.",steps:[{say:"Open the place. It leads with the walk you have been asked to do and when it is due, then what you will do most: walk round, report a problem, take a reading, write something down.",tryIt:{as:"usr_kudzai",to:`/properties/${s}`,label:"Open it as Kudzai"}},{say:"Walk round with your phone: the outside, the rooms, the tank, the gate, the meter. Say what changed since the last walk, and photograph it.",showing:{propertyId:s,conditionId:"cond_hill_walk_2"}},{say:"Something broken goes in as a report, with a photograph. It reaches the owner, who decides what is done and what it costs, and you can see where it has got to.",showing:{propertyId:s,requestId:"req_hill_gate"}},{say:"What you paid out for the place, a padlock or the electricity, goes under What you paid out. You read what you recorded, and the owner can say it is what they have too.",tryIt:{as:"usr_kudzai",to:`/properties/${s}/money`,label:"Record one as Kudzai"}},{say:"On a build the owner may send you money to spend on it. It sits beside what you paid out of it, two lists, and neither of you reads a balance between them.",tryIt:{as:"usr_grace",to:`/properties/${r}/money`,label:"Read both lists as Grace"}},{say:"Where somebody lives there, you walk the outside only. Inside is their home, and not yours to photograph."}],scopeNote:"Your walks are your word, dated and photographed. They are not an inspection, and nothing on them says the house is sound.",seeAlso:[{to:"/how-it-works",label:"Why every entry says who wrote it"},{to:"/evidence",label:"What your word is worth beside a check"}]},{slug:"keep-the-record-before-the-owner-is-on-it",title:"The owner is not on Den & Keyholder yet. Can you keep the record and hand it over later?",forWhom:["caretaker"],minutes:3,situation:"Hillside house in Bulawayo, which Kudzai kept for his cousin Farai until Farai took it.",steps:[{say:"Add the place, and where it asks whose it is, say you look after it for somebody. You keep the record as the one who looks after it, never in the owner’s chair.",tryIt:{as:"usr_kudzai",to:"/properties/new",label:"Add one as Kudzai"}},{say:"Authorising checks is the owner’s to give, so on your record it starts unasked, and no check is ordered until the owner is on it to give it."},{say:"Then keep it as you would any place you look after: walks, reports, readings and what you paid out. Each entry is in your name."},{say:"When the owner is ready, Hand the record to the owner makes a code. You send it however you already talk to them, and the page it opens says who kept the record and since when."},{say:"Once they take it, the record is theirs. You stay on it, looking after the place, everything you filed keeps your name, and the History says on which day it changed hands.",tryIt:{as:"usr_farai",to:`/properties/${s}/history`,label:"Read Hillside’s as Farai"}}],seeAlso:[{to:"/how-it-works",label:"Who keeps a record, and what changes when it changes hands"}]},{slug:"take-the-record-kept-for-you",title:"Somebody has kept the record of your house for you. What happens when you take it?",forWhom:["owner"],minutes:2,situation:"Hillside house in Bulawayo, which Kudzai kept for his cousin Farai and Farai took.",steps:[{say:"The code comes from whoever kept the record. The page it opens says whose record it is, who kept it and since when, before you take anything."},{say:"Taking it makes the record yours. Whoever kept it stays on it as what they were, the one who looks after the place or the builder, and reads their own part of it, never your decisions.",tryIt:{as:"usr_farai",to:`/properties/${s}/people`,label:"See who is on it as Farai"}},{say:"Nothing is rewritten. Everything filed before keeps the name of whoever filed it, and the History has a line for the day you took it, and from whom.",tryIt:{as:"usr_farai",to:`/properties/${s}/history`,label:"Read the History as Farai"}},{say:"Authorising checks was nobody’s to give while somebody else kept the record. It is yours now, and it is not given until you give it."}],seeAlso:[{to:"/how-it-works",label:"Who keeps a record, and what changes when it changes hands"}]}],y=h=>l.find(d=>d.slug===h),u={tenanted:["condition-before-they-move-in","bring-somebody-onto-a-place","a-repair-you-are-asked-to-pay-for"],home:["nothing-is-wrong-this-month","keep-what-you-need-in-a-hurry","what-a-place-costs-you"],renting:["the-first-week-of-a-lease","something-broke-tell-your-landlord","get-the-rent-confirmed"],building:["before-it-is-covered","money-for-a-builder","which-check-do-i-need"],family:["a-repair-you-are-asked-to-pay-for","report-without-approving","which-check-do-i-need"],vacant:["which-check-do-i-need","bring-somebody-onto-a-place","a-repair-you-are-asked-to-pay-for"],renovating:["before-it-is-covered","money-for-a-builder","deliveries-and-changes"],staying:["keep-a-record-of-a-stay","something-broke-tell-your-landlord","what-a-place-costs-you"],hosting:["keep-what-you-need-in-a-hurry","send-a-pack-outside-the-account","nothing-is-wrong-this-month"]},p=["something-broke-tell-your-landlord","keep-a-record-of-a-stay","nothing-is-wrong-this-month"];export{p as F,l as G,u as a,y as g};
